def majority_element(nums):
    candidate, count = None, 0
    for n in nums:
        if count == 0:
            candidate = n
        count += 1 if n == candidate else -1
    return candidate

def kmp(text, pattern):
    # Build failure table
    fail = [0] * len(pattern)
    k = 0
    for i in range(1, len(pattern)):
        while k > 0 and pattern[k] != pattern[i]:
            k = fail[k - 1]
        if pattern[k] == pattern[i]:
            k += 1
        fail[i] = k
    # Match
    j = 0
    for i in range(len(text)):
        while j > 0 and pattern[j] != text[i]:
            j = fail[j - 1]
        if pattern[j] == text[i]:
            j += 1
        if j == len(pattern):
            return i - j + 1
    return -1

def rabin_karp(text, pattern):
    n, m = len(text), len(pattern)
    if m > n: return -1
    base, mod = 256, 10**9 + 7
    p_hash = t_hash = 0
    h = pow(base, m - 1, mod)
    for i in range(m):
        p_hash = (p_hash * base + ord(pattern[i])) % mod
        t_hash = (t_hash * base + ord(text[i])) % mod
    for i in range(n - m + 1):
        if p_hash == t_hash and text[i:i+m] == pattern:
            return i
        if i < n - m:
            t_hash = ((t_hash - ord(text[i]) * h) * base + ord(text[i+m])) % mod
            t_hash %= mod
    return -1

def z_array(s):
    n = len(s)
    z = [0] * n
    z[0] = n
    l = r = 0
    for i in range(1, n):
        if i < r:
            z[i] = min(r - i, z[i - l])
        while i + z[i] < n and s[z[i]] == s[i + z[i]]:
            z[i] += 1
        if i + z[i] > r:
            l, r = i, i + z[i]
    return z

class SegTree:
    def __init__(self, n):
        self.n = n
        self.t = [0] * (4 * n)
    def update(self, i, val, node=1, lo=0, hi=None):
        if hi is None: hi = self.n - 1
        if lo == hi:
            self.t[node] = val; return
        mid = (lo + hi) // 2
        if i <= mid: self.update(i, val, 2*node, lo, mid)
        else:        self.update(i, val, 2*node+1, mid+1, hi)
        self.t[node] = self.t[2*node] + self.t[2*node+1]
    def query(self, l, r, node=1, lo=0, hi=None):
        if hi is None: hi = self.n - 1
        if r < lo or hi < l: return 0
        if l <= lo and hi <= r: return self.t[node]
        mid = (lo + hi) // 2
        return (self.query(l, r, 2*node, lo, mid) +
                self.query(l, r, 2*node+1, mid+1, hi))

class BIT:
    def __init__(self, n):
        self.n = n
        self.t = [0] * (n + 1)
    def update(self, i, delta):  # 1-indexed
        while i <= self.n:
            self.t[i] += delta
            i += i & -i
    def query(self, i):  # prefix sum [1..i]
        s = 0
        while i > 0:
            s += self.t[i]
            i -= i & -i
        return s
    def range_query(self, l, r):
        return self.query(r) - self.query(l - 1)

def floyd_warshall(graph, n):
    # graph[i][j] = weight, INF if no edge
    INF = float('inf')
    dist = [row[:] for row in graph]
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]
    return dist

def bellman_ford(edges, n, source):
    INF = float('inf')
    dist = [INF] * n
    dist[source] = 0
    for _ in range(n - 1):
        for u, v, w in edges:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
    # Detect negative cycle
    for u, v, w in edges:
        if dist[u] + w < dist[v]:
            return None  # negative cycle
    return dist

import heapq

def a_star(graph, start, goal, h):
    # h(node) = estimated cost from node to goal
    pq = [(h(start), 0, start)]  # (f, g, node)
    came_from = {}
    g_score = {start: 0}
    while pq:
        f, g, node = heapq.heappop(pq)
        if node == goal:
            return reconstruct(came_from, node)
        for nb, w in graph[node]:
            tg = g + w
            if tg < g_score.get(nb, float('inf')):
                came_from[nb] = node
                g_score[nb] = tg
                heapq.heappush(pq, (tg + h(nb), tg, nb))
    return None

def reconstruct(came, node):
    path = [node]
    while node in came:
        node = came[node]
        path.append(node)
    return path[::-1]

def tarjan_scc(graph, n):
    index = [0]
    indices = [-1] * n
    lowlinks = [0] * n
    on_stack = [False] * n
    stack = []
    sccs = []
    def strongconnect(v):
        indices[v] = lowlinks[v] = index[0]
        index[0] += 1
        stack.append(v); on_stack[v] = True
        for w in graph[v]:
            if indices[w] == -1:
                strongconnect(w)
                lowlinks[v] = min(lowlinks[v], lowlinks[w])
            elif on_stack[w]:
                lowlinks[v] = min(lowlinks[v], indices[w])
        if lowlinks[v] == indices[v]:
            scc = []
            while True:
                w = stack.pop(); on_stack[w] = False
                scc.append(w)
                if w == v: break
            sccs.append(scc)
    for v in range(n):
        if indices[v] == -1:
            strongconnect(v)
    return sccs

import heapq

def prim(graph, start, n):
    # graph[u] = [(v, w), ...]
    visited = {start}
    pq = [(w, start, v) for v, w in graph[start]]
    heapq.heapify(pq)
    mst, total = [], 0
    while pq and len(visited) < n:
        w, u, v = heapq.heappop(pq)
        if v in visited: continue
        visited.add(v); mst.append((u, v, w)); total += w
        for nb, nw in graph[v]:
            if nb not in visited:
                heapq.heappush(pq, (nw, v, nb))
    return mst, total

from collections import deque

def hopcroft_karp(adj, U, V):
    INF = float('inf')
    pair_u = {u: None for u in U}
    pair_v = {v: None for v in V}
    dist = {}
    def bfs():
        q = deque()
        for u in U:
            if pair_u[u] is None: dist[u] = 0; q.append(u)
            else: dist[u] = INF
        found = False
        while q:
            u = q.popleft()
            for v in adj[u]:
                pair = pair_v[v]
                if pair is None: found = True
                elif dist.get(pair, INF) == INF:
                    dist[pair] = dist[u] + 1; q.append(pair)
        return found
    def dfs(u):
        for v in adj[u]:
            pair = pair_v[v]
            if pair is None or (dist.get(pair, INF) == dist[u] + 1 and dfs(pair)):
                pair_u[u] = v; pair_v[v] = u; return True
        dist[u] = INF
        return False
    matching = 0
    while bfs():
        for u in U:
            if pair_u[u] is None and dfs(u):
                matching += 1
    return matching

def convex_hull(points):
    points = sorted(set(points))
    if len(points) <= 1: return points
    def cross(O, A, B):
        return (A[0]-O[0])*(B[1]-O[1]) - (A[1]-O[1])*(B[0]-O[0])
    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]

import random

def reservoir_sample(stream, k):
    reservoir = []
    for i, item in enumerate(stream):
        if i < k:
            reservoir.append(item)
        else:
            j = random.randint(0, i)
            if j < k:
                reservoir[j] = item
    return reservoir

def find_cycle_start(head):
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            slow = head
            while slow is not fast:
                slow = slow.next
                fast = fast.next
            return slow
    return None  # no cycle

from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity):
        self.cap = capacity
        self.cache = OrderedDict()
    def get(self, key):
        if key not in self.cache: return -1
        self.cache.move_to_end(key)
        return self.cache[key]
    def put(self, key, value):
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.cap:
            self.cache.popitem(last=False)

import hashlib

class BloomFilter:
    def __init__(self, size, k):
        self.size = size
        self.k = k
        self.bits = [False] * size
    def _hashes(self, item):
        h = hashlib.md5(str(item).encode()).digest()
        # use bytes of digest as k separate hashes
        return [h[i] * 256 + h[i + 1] % self.size for i in range(self.k)]
    def add(self, item):
        for idx in self._hashes(item):
            self.bits[idx % self.size] = True
    def __contains__(self, item):
        return all(self.bits[idx % self.size] for idx in self._hashes(item))

import random

class SkipNode:
    def __init__(self, key, levels):
        self.key = key
        self.next = [None] * levels

class SkipList:
    def __init__(self, max_level=16, p=0.5):
        self.max_level = max_level
        self.p = p
        self.head = SkipNode(None, max_level)
        self.level = 0
    def _rand_level(self):
        lvl = 1
        while random.random() < self.p and lvl < self.max_level:
            lvl += 1
        return lvl
    def insert(self, key):
        update = [self.head] * self.max_level
        x = self.head
        for i in range(self.level - 1, -1, -1):
            while x.next[i] and x.next[i].key < key:
                x = x.next[i]
            update[i] = x
        lvl = self._rand_level()
        if lvl > self.level:
            for i in range(self.level, lvl): update[i] = self.head
            self.level = lvl
        new = SkipNode(key, lvl)
        for i in range(lvl):
            new.next[i] = update[i].next[i]
            update[i].next[i] = new

def catalan(n):
    # via DP
    C = [0] * (n + 1)
    C[0] = 1
    for i in range(1, n + 1):
        for j in range(i):
            C[i] += C[j] * C[i - 1 - j]
    return C[n]

def num_bsts(n):  # number of structurally distinct BSTs with n keys
    return catalan(n)

def matmul(A, B, mod=None):
    n, m, p = len(A), len(B), len(B[0])
    C = [[0]*p for _ in range(n)]
    for i in range(n):
        for k in range(m):
            if A[i][k]:
                for j in range(p):
                    C[i][j] += A[i][k] * B[k][j]
                    if mod: C[i][j] %= mod
    return C

def matpow(M, p, mod=None):
    n = len(M)
    result = [[1 if i==j else 0 for j in range(n)] for i in range(n)]
    base = [row[:] for row in M]
    while p:
        if p & 1: result = matmul(result, base, mod)
        base = matmul(base, base, mod)
        p >>= 1
    return result

def fib(n):
    if n == 0: return 0
    M = [[1, 1], [1, 0]]
    return matpow(M, n)[0][1]

import math

def preprocess(adj, root, n):
    LOG = max(1, int(math.log2(n)) + 1)
    up = [[-1] * n for _ in range(LOG)]
    depth = [0] * n
    # BFS or DFS to fill depth and up[0]
    def dfs(u, parent, d):
        up[0][u] = parent
        depth[u] = d
        for v in adj[u]:
            if v != parent: dfs(v, u, d + 1)
    dfs(root, -1, 0)
    for k in range(1, LOG):
        for v in range(n):
            if up[k-1][v] != -1:
                up[k][v] = up[k-1][up[k-1][v]]
    return up, depth, LOG

def lca(u, v, up, depth, LOG):
    if depth[u] < depth[v]: u, v = v, u
    diff = depth[u] - depth[v]
    for k in range(LOG):
        if (diff >> k) & 1: u = up[k][u]
    if u == v: return u
    for k in range(LOG - 1, -1, -1):
        if up[k][u] != up[k][v]:
            u = up[k][u]; v = up[k][v]
    return up[0][u]

def sieve(n):
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, int(n**0.5) + 1):
        if is_prime[p]:
            for multiple in range(p*p, n + 1, p):
                is_prime[multiple] = False
    return [i for i, prime in enumerate(is_prime) if prime]
